import type {
  Issue,
  IssueAttachment,
  IssueDependency,
  IssueLabel,
} from "@/types/issue";

export function toIssueDependency(row: IssueDependencyRow): IssueDependency {
  return {
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    blockerId: brandId<IssueId>(row.blockerId),
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: brandStamp(row.createdAt),
  };
}

export function toIssue(

/**
 * Directed "blocked by" edges. Every query is scoped by `orgId`.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { and, asc, eq } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { livePredicate, orgPredicate } from "./base-repository";
import { toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";

const CLOSED_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

export async function insertDependency(
  link: IssueDependency,
): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId: link.orgId,
      issueId: link.issueId,
      blockerId: link.blockerId,
      createdBy: link.createdBy,
      createdAt: link.createdAt,
    })
    .returning()
    .get();
  return toIssueDependency(row);
}

/** Resolves `true` when a row was deleted. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning()
    .all();
  return rows.length > 0;
}

/** Non-archived blockers of `issueId`, issue number ascending. */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(eq(issues.id, issueDependencies.blockerId), eq(issues.orgId, orgId)),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        livePredicate(issues.archivedAt, {}),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();

  return withLabels(
    orgId,
    rows.map((row) => row.issue),
  );
}

/** Blockers that still stop completion: live and neither done nor canceled. */
export async function listOpenBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const blockers = await listBlockerIssues(orgId, issueId);
  return blockers.filter((issue) => !CLOSED_STATUSES.includes(issue.status));
}

/** Every issue that lists `blockerId` as a blocker, archived or not. */
export async function listIssuesBlockedBy(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(eq(issues.id, issueDependencies.issueId), eq(issues.orgId, orgId)),
    )
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();

  return withLabels(
    orgId,
    rows.map((row) => row.issue),
  );
}

/** Every edge in the org, used to reject links that would close a cycle. */
export async function listEdges(
  orgId: OrgId,
): Promise<readonly { issueId: IssueId; blockerId: IssueId }[]> {
  const rows = getDb()
    .select({
      issueId: issueDependencies.issueId,
      blockerId: issueDependencies.blockerId,
    })
    .from(issueDependencies)
    .where(orgPredicate(issueDependencies.orgId, orgId))
    .all();

  return rows.map((row) => ({
    issueId: row.issueId as IssueId,
    blockerId: row.blockerId as IssueId,
  }));
}

async function withLabels(
  orgId: OrgId,
  rows: readonly (typeof issues.$inferSelect)[],
): Promise<readonly Issue[]> {
  if (rows.length === 0) return [];
  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

// `livePredicate` is the only sanctioned archived filter; referencing the
// helper keeps this module on the soft-delete path even if a future query
// forgets to compose it.
void livePredicate;

/**
 * Blocked-by links: who may edit them, which graphs are legal, and the notification fired when the last open blocker closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/**
 * Raised when an issue is moved to `done` while a blocker is still open.
 * `blockerIds` is exactly that open set; the issue row is left untouched.
 */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;
  readonly blockerIds: readonly IssueId[];

  constructor(blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
    this.blockerIds = [...blockerIds];
  }
}

export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );

  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  if (input.issueId === input.blockerId) {
    throw new Error("An issue cannot block itself");
  }

  const edges = await dependencyRepo.listEdges(input.orgId);
  if (createsCycle(input.issueId, input.blockerId, edges)) {
    throw new Error("Adding this blocker would create a dependency cycle");
  }

  return dependencyRepo.insertDependency({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
    createdAt: toIsoTimestamp(new Date()),
  });
}

export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issueId);
}

/**
 * Completion gate shared by every status-change path. Throws
 * `IssueBlockedError` when `done` would be reached with an open blocker.
 */
export async function assertCanMarkDone(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const open = await dependencyRepo.listOpenBlockers(orgId, issueId);
  if (open.length > 0) {
    throw new IssueBlockedError(open.map((issue) => issue.id));
  }
}

/**
 * An archived issue is a closed blocker when its status was still open.
 * Called from the archive event and from the project cascade, which archives
 * issues without emitting `issue.archived` per row.
 */
export async function handleIssueArchived(
  orgId: OrgId,
  issueId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue || issue.archivedAt === null) return;
  if (isClosedStatus(issue.status)) return;
  await notifyUnblockedDependents(orgId, issueId, actorId);
}

/** Attaches the unblock fan-out. Wired from `registerEventHandlers()`. */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (!isClosedStatus(payload.to) || isClosedStatus(payload.from)) return;
      await notifyUnblockedDependents(
        payload.orgId,
        payload.issueId,
        payload.actorId,
      );
    }),
    subscribe("issue.archived", async (payload) => {
      await handleIssueArchived(
        payload.orgId,
        payload.issueId,
        payload.actorId,
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * True when `blockerId` can already reach `issueId` by following "blocked by"
 * edges, so the new edge `issueId -> blockerId` would close a cycle.
 */
function createsCycle(
  issueId: IssueId,
  blockerId: IssueId,
  edges: readonly { issueId: IssueId; blockerId: IssueId }[],
): boolean {
  const blockersOf = new Map<string, string[]>();
  for (const edge of edges) {
    const next = blockersOf.get(edge.issueId) ?? [];
    next.push(edge.blockerId);
    blockersOf.set(edge.issueId, next);
  }

  const seen = new Set<string>();
  const stack = [blockerId as string];
  while (stack.length > 0) {
    const current = stack.pop() as string;
    if (current === issueId) return true;
    if (seen.has(current)) continue;
    seen.add(current);
    for (const next of blockersOf.get(current) ?? []) stack.push(next);
  }
  return false;
}

async function notifyUnblockedDependents(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const dependents = await dependencyRepo.listIssuesBlockedBy(orgId, blockerId);
  const ready: Issue[] = [];

  for (const issue of dependents) {
    if (issue.archivedAt !== null) continue;
    if (isClosedStatus(issue.status)) continue;
    if (issue.assigneeId === null) continue;
    const open = await dependencyRepo.listOpenBlockers(orgId, issue.id);
    if (open.length > 0) continue;
    ready.push(issue);
  }

  if (ready.length === 0) return;

  const { notify } = await import("./notification-service");
  for (const issue of ready) {
    await notify(orgId, "issue_unblocked", [issue.assigneeId as UserId], {
      title: "Issue unblocked",
      body: `${issue.title} is no longer blocked`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

