let direct = false;
try {
  await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: b.id, blockerId: a.id });
} catch (error) {
  direct = error instanceof Error;
}
check("direct cycle", direct);

await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: b.id, blockerId: c.id });
let indirect = false;
try {
  await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: c.id, blockerId: a.id });
} catch (error) {
  indirect = error instanceof Error;
}
check("indirect cycle", indirect);

// diamond is not a cycle: a blocked by c while a blocked by b blocked by c
const diamond = await dep.addBlocker(actor, {
  orgId: tenant.org.id,
  issueId: a.id,
  blockerId: c.id,
});
check("diamond", diamond.blockerId === c.id);

let cross = false;
try {
  await dep.addBlocker(actor, {
    orgId: tenant.org.id,
    issueId: a.id,
    blockerId: other.project.id as never,
  });
} catch (error) {
  cross = error instanceof NotFoundError;
}
check("unknown blocker not found", cross);

const foreign = await make.call(null, "no");
// issue in other org
const otherIssue = await issueService.createIssue(
  other.actors.member,
  fixtures.issueInput(other.org.id, other.project.id, { title: "Foreign" }),
);
let otherOrg = false;
try {
  await dep.addBlocker(actor, {
    orgId: tenant.org.id,
    issueId: a.id,
    blockerId: otherIssue.id,
  });
} catch (error) {
  otherOrg = error instanceof NotFoundError;
}
check("other org issue not found", otherOrg);

let scope = false;
try {
  await dep.addBlocker(actor, {
    orgId: other.org.id,
    issueId: otherIssue.id,
    blockerId: otherIssue.id,
  });
} catch (error) {
  scope = error instanceof TenantScopeError;
}
check("tenant scope", scope);

let denied = false;
try {
  const d = await make("D");
  const e = await make("E");
  await dep.addBlocker(viewer, { orgId: tenant.org.id, issueId: d.id, blockerId: e.id });
} catch (error) {
  denied = error instanceof PermissionDeniedError;
}
check("permission", denied);

const arch1 = await make("Arch1");
const arch2 = await make("Arch2");
await issueService.archiveIssue(actor, tenant.org.id, arch1.id);
let archived = false;
try {
  await dep.addBlocker(actor, {
    orgId: tenant.org.id,
    issueId: arch1.id,
    blockerId: arch2.id,
  });
} catch (error) {
  archived = error instanceof AlreadyArchivedError;
}
check("archived blocked", archived);
let archivedBlocker = false;
try {
  await dep.addBlocker(actor, {
    orgId: tenant.org.id,
    issueId: arch2.id,
    blockerId: arch1.id,
  });
} catch (error) {
  archivedBlocker = error instanceof AlreadyArchivedError;
}
check("archived blocker", archivedBlocker);

const blocked = await make("Blocked done", tenant.userIds.admin);
const blocker = await make("Blocker open", tenant.userIds.member);
await dep.addBlocker(actor, {
  orgId: tenant.org.id,
  issueId: blocked.id,
  blockerId: blocker.id,
});

const seen: string[] = [];
const off = bus.subscribe("issue.status_changed", () => {
  seen.push("status");
});
let blockedErr: { code?: string; blockerIds?: string[] } | null = null;
try {
  await issueService.changeIssueStatus(actor, {
    orgId: tenant.org.id,
    issueId: blocked.id,
    status: "done",
  });
} catch (error) {
  if (error instanceof dep.IssueBlockedError) {
    blockedErr = { code: error.code, blockerIds: [...error.blockerIds] };
  }
}
off();
check(
  "done rejected",
  blockedErr?.code === "conflict" && blockedErr.blockerIds?.length === 1 && blockedErr.blockerIds[0] === blocker.id,
  JSON.stringify(blockedErr),
);
check("no status event", seen.length === 0);
const still = await issueService.getIssue(actor, tenant.org.id, blocked.id);
check("unchanged", still.issue.status === "backlog");

await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: blocked.id,
  status: "canceled",
});
const canceled = await issueService.getIssue(actor, tenant.org.id, blocked.id);
check("canceled allowed", canceled.issue.status === "canceled");
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: blocked.id,
  status: "todo",
});

let moveThrew = false;
try {
  await issueService.moveIssue(actor, {
    orgId: tenant.org.id,
    issueId: blocked.id,
    toStatus: "done",
    toIndex: 0,
  });
} catch (error) {
  moveThrew = error instanceof dep.IssueBlockedError;
}
check("move done rejected", moveThrew);

// close blocker -> notify assignee (admin), actor is member
const beforeNotifs = await notifRepo.listNotifications({
  orgId: tenant.org.id,
  recipientId: tenant.userIds.admin,
  unreadOnly: false,
  kind: ["issue_unblocked"],
  limit: 50,
  cursor: null,
});
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: blocker.id,
  status: "done",
});
const afterNotifs = await notifRepo.listNotifications({
  orgId: tenant.org.id,
  recipientId: tenant.userIds.admin,
  unreadOnly: false,
  kind: ["issue_unblocked"],
  limit: 50,
  cursor: null,
});
const created = afterNotifs.items.filter(
  (row) => !beforeNotifs.items.some((prev) => prev.id === row.id),
);
check(
  "unblocked notify",
  created.length === 1 &&
    created[0]?.href === `/issues/${blocked.id}` &&
    created[0]?.actorId === actor.userId &&
    created[0]?.kind === "issue_unblocked",
  JSON.stringify(created),
);

// reopen and close again notifies again
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: blocker.id,
  status: "in_progress",
});
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: blocker.id,
  status: "done",
});
const twice = await notifRepo.listNotifications({
  orgId: tenant.org.id,
  recipientId: tenant.userIds.admin,
  unreadOnly: false,
  kind: ["issue_unblocked"],
  limit: 50,
  cursor: null,
});
const forBlocked = twice.items.filter((row) => row.href === `/issues/${blocked.id}`);
check("notifies again", forBlocked.length === 2, String(forBlocked.length));

// done -> canceled does not notify
const countBefore = forBlocked.length;
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: blocker.id,
  status: "canceled",
});
const afterClosed = await notifRepo.listNotifications({
  orgId: tenant.org.id,
  recipientId: tenant.userIds.admin,
  unreadOnly: false,
  kind: ["issue_unblocked"],
  limit: 50,
  cursor: null,
});
check(
  "closed to closed silent",
  afterClosed.items.filter((row) => row.href === `/issues/${blocked.id}`).length === countBefore,
);

// second open blocker suppresses
const blocked2 = await make("Needs two", tenant.userIds.admin);
const b1 = await make("B1", tenant.userIds.member);
const b2 = await make("B2", tenant.userIds.member);
await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: blocked2.id, blockerId: b1.id });
await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: blocked2.id, blockerId: b2.id });
const n0 = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${blocked2.id}`).length;
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: b1.id,
  status: "done",
});
const n1 = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${blocked2.id}`).length;
check("still blocked silent", n1 === n0);
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: b2.id,
  status: "done",
});
const n2 = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${blocked2.id}`).length;
check("last blocker notifies", n2 === n0 + 1);

// self action not notified
const selfBlocked = await make("Self blocked", tenant.userIds.member);
const selfBlocker = await make("Self blocker", null);
await dep.addBlocker(actor, {
  orgId: tenant.org.id,
  issueId: selfBlocked.id,
  blockerId: selfBlocker.id,
});
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: selfBlocker.id,
  status: "done",
});
const selfRows = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.member,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${selfBlocked.id}`);
check("no self notify", selfRows.length === 0, String(selfRows.length));

// preference mute
const mutedBlocked = await make("Muted", tenant.userIds.admin);
const mutedBlocker = await make("Muted blocker", null);
await dep.addBlocker(actor, {
  orgId: tenant.org.id,
  issueId: mutedBlocked.id,
  blockerId: mutedBlocker.id,
});
await prefRepo.upsertPreference({
  orgId: tenant.org.id,
  userId: tenant.userIds.admin,
  kind: "issue_unblocked",
  inApp: false,
  email: false,
  digestOnly: false,
});
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: mutedBlocker.id,
  status: "done",
});
const mutedRows = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${mutedBlocked.id}`);
check("muted", mutedRows.length === 0);
// restore preference so later notifies work
await prefRepo.upsertPreference({
  orgId: tenant.org.id,
  userId: tenant.userIds.admin,
  kind: "issue_unblocked",
  inApp: true,
  email: true,
  digestOnly: false,
});

// archive open blocker notifies
const archBlocked = await make("Arch blocked", tenant.userIds.admin);
const archBlocker = await make("Arch blocker", null);
await dep.addBlocker(actor, {
  orgId: tenant.org.id,
  issueId: archBlocked.id,
  blockerId: archBlocker.id,
});
await issueService.archiveIssue(actor, tenant.org.id, archBlocker.id);
const archRows = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${archBlocked.id}`);
check("archive notifies", archRows.length === 1 && archRows[0]?.actorId === actor.userId);

// archive already closed does not notify
const closedBlocked = await make("Closed blocked", tenant.userIds.admin);
const closedBlocker = await make("Closed blocker", null);
await dep.addBlocker(actor, {
  orgId: tenant.org.id,
  issueId: closedBlocked.id,
  blockerId: closedBlocker.id,
});
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: closedBlocker.id,
  status: "canceled",
});
const pre = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${closedBlocked.id}`).length;
await issueService.archiveIssue(actor, tenant.org.id, closedBlocker.id);
const post = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${closedBlocked.id}`).length;
check("archive closed silent", pre === 0 && post === 0, `${pre} ${post}`);

// remove never notifies
const rmBlocked = await make("Rm blocked", tenant.userIds.admin);
const rmBlocker = await make("Rm blocker", null);
await dep.addBlocker(actor, {
  orgId: tenant.org.id,
  issueId: rmBlocked.id,
  blockerId: rmBlocker.id,
});
const removed = await dep.removeBlocker(actor, {
  orgId: tenant.org.id,
  issueId: rmBlocked.id,
  blockerId: rmBlocker.id,
});
const rmRows = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 50,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${rmBlocked.id}`);
check("remove true silent", removed === true && rmRows.length === 0);
const removedAgain = await dep.removeBlocker(actor, {
  orgId: tenant.org.id,
  issueId: rmBlocked.id,
  blockerId: rmBlocker.id,
});
check("remove missing", removedAgain === false);

// remove does not require blocker to exist
const ghostBlocked = await make("Ghost", null);
const removedGhost = await dep.removeBlocker(actor, {
  orgId: tenant.org.id,
  issueId: ghostBlocked.id,
  blockerId: "01HZZZGHOSTGHOSTGHOSTGHOST" as never,
});
check("remove ghost blocker", removedGhost === false);

// list order by number
const low = await make("Low num");
const high = await make("High num");
const target = await make("Target");
// numbers increase with creation, so low.number < high.number
await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: target.id, blockerId: high.id });
await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: target.id, blockerId: low.id });
const ordered = await dep.listBlockers(actor, tenant.org.id, target.id);
check(
  "order",
  ordered.map((issue) => issue.id).join() === [low.id, high.id].join(),
  ordered.map((issue) => issue.number).join(","),
);

// archived blocker hidden from list but closed blocker shown
await issueService.archiveIssue(actor, tenant.org.id, low.id);
const visible = await dep.listBlockers(actor, tenant.org.id, target.id);
check("hides archived blocker", visible.length === 1 && visible[0]?.id === high.id);
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: high.id,
  status: "done",
});
const stillListed = await dep.listBlockers(actor, tenant.org.id, target.id);
check("shows closed blocker", stillListed.length === 1 && stillListed[0]?.status === "done");

// no assignee, done dependent, archived dependent skipped
const noAssignee = await make("No assignee", null);
const doneDep = await make("Already done", tenant.userIds.admin);
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: doneDep.id,
  status: "done",
});
const archDep = await make("Arch dep", tenant.userIds.admin);
await issueService.archiveIssue(actor, tenant.org.id, archDep.id);
const shared = await make("Shared blocker", null);
await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: noAssignee.id, blockerId: shared.id });
// done dep can't be linked if we... done issue is not archived, add is allowed
await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: doneDep.id, blockerId: shared.id });
let archLink = false;
try {
  await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: archDep.id, blockerId: shared.id });
} catch (error) {
  archLink = error instanceof AlreadyArchivedError;
}
check("cannot link archived dependent", archLink);
// manually we need an archived dependent that was linked before archive
const laterArch = await make("Later arch", tenant.userIds.admin);
await dep.addBlocker(actor, { orgId: tenant.org.id, issueId: laterArch.id, blockerId: shared.id });
await issueService.archiveIssue(actor, tenant.org.id, laterArch.id);
const preShared = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 80,
    cursor: null,
  })
).items.length;
await issueService.changeIssueStatus(actor, {
  orgId: tenant.org.id,
  issueId: shared.id,
  status: "done",
});
const postShared = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 80,
    cursor: null,
  })
).items;
check("skip ineligible dependents", postShared.length === preShared);

// schema accepts the kind
check(
  "zod kind",
  schema.notificationKindSchema.safeParse("issue_unblocked").success === true,
);

// project cascade archive notifies
const pBlocked = await make("Proj blocked", tenant.userIds.admin);
const pBlocker = await make("Proj blocker", null);
await dep.addBlocker(actor, {
  orgId: tenant.org.id,
  issueId: pBlocked.id,
  blockerId: pBlocker.id,
});
// blocker must live in the archived project — both are in tenant.project
// but pBlocked is also in that project and would be archived too, so it would
// not be notified (archived dependent). Put the blocked issue... both same project.
// Archiving the project archives BOTH, so the dependent is archived and should NOT notify.
await projectService.archiveProject(tenant.actors.admin, {
  orgId: tenant.org.id,
  projectId: tenant.project.id,
  archiveIssues: true,
});
const projRows = (
  await notifRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_unblocked"],
    limit: 80,
    cursor: null,
  })
).items.filter((row) => row.href === `/issues/${pBlocked.id}`);
check("project cascade skips archived dependent", projRows.length === 0);

// remove missing issue
let missingIssue = false;
try {
  await dep.removeBlocker(actor, {
    orgId: tenant.org.id,
    issueId: "01HZZZMISSINGMISSINGMISSING" as never,
    blockerId: b.id,
  });
} catch (error) {
  missingIssue = error instanceof NotFoundError;
}
check("remove missing issue", missingIssue);

